from dataclasses import asdict
from ..device import CalibrationStore
from ..hardware import BOUNDS, EXTENSION_FIELDS
from ..instruments import BOUNDS as INSTRUMENT_BOUNDS

def scalar_bounds(n):
    return {'hold_enabled': (0, 1), 'hold_freq': (0.1, 15), 'hold_phase': (-20, 20), 'hold_rise': (0.1, 500), 'cnot_pre_phase': (-20, 20), 'cnot_frame_phase': (-20, 20), 'drive_freq': (0.1, 15), 'readout_freq': (0.1, 15), 'pi_amp': (0.0001, 2), 'pi_duration': (1, 2000), 'drag': (-5, 5), 'anharm': (-1, -0.001), 'iq_angle': (-20, 20), 'iq_threshold': (-2000, 2000), 'readout_amplitude': (0, 1000), 'readout_duration': (1, 20000), 'drive_line': (0, n - 1), 'cr_amp': (-2, 2), 'cr_duration': (1, 20000), 'cr_phase': (-20, 20), 'cr_rise': (0.1, 10000), 'cr_drag': (-5, 5), 'ecr_balance': (-0.99, 0.99), 'ecr_phase_skew': (-20, 20), 'sizzle_freq': (0.1, 15), 'sizzle_phase': (-20, 20), 'sizzle_duration': (1, 20000), 'sizzle_rise': (0.1, 10000), 'idle_active': (0, 1), 'idle_tone_freq': (0.1, 15), 'idle_tone_amp': (0, 2), 'idle_tone_phase': (-20, 20), 'idle_tone_rise': (0.1, 500), 'idle_frame_phase': (-20, 20), 'idle_tone_smooth': (0, 1), 'sizzle_smooth': (0, 1), 'hold_smooth': (0, 1), 'ecr_walsh': (0, 1), **BOUNDS, **INSTRUMENT_BOUNDS}
DESCRIPTIONS = {'dressing_freq': 'Continuous off-resonant microwave dressing carrier, GHz (default 5.2). Physically shifts the qubit through the AC Stark effect. Three-level backends use a dispersive approximation; the full-cosine backend propagates the continuous tone explicitly.', 'dressing_amp': 'Continuous microwave dressing source amplitude (default zero). Recalibrate drive carrier and pulses after changing the dressed operating point.', 'ampm_compensation': 'Memoryless source phase predistortion c: z -> z exp(i c |z|^2), before physical AM-PM distortion; rad/amplitude squared. Applies to the summed source waveform, including DRAG.', 'readout_time_of_flight': 'ADC integration-window start relative to emitted readout, ns; distinct from drive channel_delay.', 'adc_offset_i': 'Input-referred additive I offset correction for the linear receiver.', 'adc_offset_q': 'Input-referred additive Q offset correction for the linear receiver.', 'adc_gain': 'Positive linear receiver gain correction (not dB).', 'lo_freq': 'Physical source LO in GHz (default 5.0). Commanded RF is unchanged; signed IF=RF-LO and image=2*LO-RF.', 'mixer_gain': 'Digital Q/I gain before the physical IQ mixer; default 1.', 'mixer_skew': 'Digital quadrature skew in radians; default 0.', 'mixer_dc_i': 'Physical-source I DC offset in command amplitude units; default 0.', 'mixer_dc_q': 'Physical-source Q DC offset in command amplitude units; default 0.', 'channel_delay': 'Signed source timing correction in ns. Advanced/delayed tails are retained and charged.', 'flux_bias': 'DC flux in Phi0 along a fixed hardware response law. Does not update drive_freq or other calibration fields.', 'dd_sequence': 'Installed finite-pulse idle program: off/cpmg/xy4/xy8. Preserves the requested total idle window.', 'dd_pulses': 'Even CPMG pulse count (default 2). XY4/XY8 use 4/8 pulses.', 'dd_offset': 'Per-qubit DD center offset as a fraction of pulse spacing; default 0.', 'dd_min_duration': 'Apply DD only at or above this idle duration in ns (default 200). Pulses must fit without clipping.', 'readout_weights': '1–256 complex [real,imag] bins on normalized window. IQ=mean(conj(weight)*time_IQ); classifier must be refitted.', 'coupler_amp': 'Peak exchange modulation in GHz. A finite sin-squared envelope multiplies the full multilevel exchange operator.', 'coupler_freq': 'Exchange modulation carrier in GHz, near a |11>-|02> or |20> transition.', 'coupler_duration': 'Total duration of the sin-squared coupler envelope, ns.', 'coupler_phase': 'Carrier phase at the start of each coupler pulse, radians.', 'idle_active': 'Key 0: enable the installed whole-device 1000 ns cancellation block. All tones are physical; the remainder is a bare wait.', 'idle_tone_freq': 'Off-resonant idle tone carrier on this logical input, GHz.', 'idle_tone_amp': 'Off-resonant idle tone amplitude on this logical input.', 'idle_tone_phase': 'Laboratory phase of this idle tone; does not follow computational virtual frames, radians.', 'idle_tone_rise': 'Rise/fall duration of this idle tone in the 1000 ns block, ns.', 'idle_tone_smooth': '1 normalizes truncated Gaussian ramps to zero amplitude at the endpoints; 0 retains the original truncated envelope.', 'sizzle_smooth': '1 uses zero-endpoint normalized Gaussian ramps for this edge CZ; 0 uses the original truncated envelope.', 'hold_smooth': 'Independent idle-cancellation ramp: 1 normalizes endpoints to zero; 0 retains the original truncated envelope. Does not inherit CZ settings.', 'ecr_walsh': '1 splits CR into four driven quarters and uses distinct finite spectator echo patterns; 0 retains the two-half sequence.', 'idle_frame_phase': 'Installed frame increment for this qubit after a physical whole-device idle block, radians.', 'sizzle_network_amp': 'One physical CZ tone amplitude per logical input, all at sizzle_freq for this edge. Used instead of the two-tone template when installed.', 'sizzle_network_phase': 'One laboratory CZ tone phase per logical input, radians.', 'post_gate_network_phase': 'One installed logical-frame increment per qubit for this edge gate; replaces legacy free frame corrections, never fitted by scorer.', 'hold_enabled': '0: bare idle. 1: use the installed siZZle cancellation block for each complete 1000 ns of pair idle; remaining time is bare. The same physical pulse and frame increment are used by probes and scoring. Applies to pair devices only.', 'hold_frame': 'Installed local logical-frame increments for one 1000 ns cancellation block, radians; never fitted by the scorer.', 'cnot_pre_phase': 'Explicit virtual-Z before each compiled CNOT (radians). It advances physical pulse phases and the carried logical frame.', 'cnot_frame_phase': 'Explicit virtual-Z frame increment after each compiled CNOT (radians), added to active-pair post_gate_phase and fixed control -pi/2. It is applied to all subsequent probes.', 'drive_freq': 'Installed f01 drive carrier (GHz); experiments may suggest but do not install it.', 'pi_amp': 'Gaussian X180 amplitude; X90 uses half this amplitude at the same duration.', 'pi_duration': 'Total Gaussian gate duration (ns); changing it does not rescale pi_amp.', 'drag': 'Gaussian derivative quadrature coefficient; uses installed anharmonicity.', 'anharm': 'Believed f12-f01 (GHz); used by DRAG and f12 preparation.', 'drive_line': 'Logical qubit to source port mapping.', 'readout_amplitude': 'Readout voltage amplitude (default 1); incident power is proportional to its square. Refit the IQ classifier after changes.', 'readout_freq': 'Readout carrier (GHz).', 'readout_duration': 'Integration time (ns).', 'iq_angle': 'Assign 1 when real(IQ*exp(-i*angle)) > iq_threshold; radians.', 'iq_threshold': 'Threshold on rotated IQ.', 'iq_means3': 'Ordered complex cluster means for levels 0,1,2.', 'cr_amp': 'CR source amplitude.', 'cr_duration': 'Total ECR driven duration (ns), excluding finite echo/local pulses.', 'cr_phase': 'CR source phase (radians).', 'cr_rise': 'Rise duration of each Gaussian-square CR pulse (ns).', 'cr_drag': 'Derivative coefficient for CR waveform.', 'cr_cancel': 'Complex target cancellation amplitude relative to CR phase.', 'cr_rotary': 'Additional complex target tone in echoed CR, relative to CR phase.', 'ecr_balance': 'First/second CR amplitudes scale by 1+balance and 1-balance.', 'ecr_phase_skew': 'Extra phase on second CR half only (radians).', 'post_gate_phase': 'Two installed local phase corrections, ordered control,target; compiled CNOT adds these explicit logical frame increments.', 'sizzle_freq': 'Shared off-resonant carrier (GHz).', 'sizzle_amp': 'Two source amplitudes, ordered pair.', 'sizzle_phase': 'Relative phase of second siZZle tone (radians).', 'sizzle_duration': 'siZZle pulse duration (ns).', 'sizzle_rise': 'siZZle ramp duration (ns).'}

def control_catalog(n, edges, allowed=None, calibration=None, device=None):
    bounds = scalar_bounds(n)
    fields = {}
    from ..parametric import CouplerCalibration, control_bounds, obsolete_control
    parametric = isinstance(calibration, CouplerCalibration)
    if parametric:
        bounds.update(control_bounds())
    for name in asdict(calibration if parametric else CalibrationStore()):
        if parametric and obsolete_control(name):
            continue
        if allowed is not None and name not in allowed:
            continue
        if device is not None:
            from ..hardware import APPARATUS_CONTROLS, apparatus_eligible
            if any((name in names for names in APPARATUS_CONTROLS.values())) and (not apparatus_eligible(device)):
                continue
            if name == 'flux_bias' and (not any(device.physics.get('flux', []))):
                continue
            if name == 'readout_weights' and (not device.physics.get('readout', {}).get('temporal')):
                continue
        if n > 2 and name in EXTENSION_FIELDS:
            continue
        pair = name.startswith(('cr_', 'ecr_', 'sizzle_', 'post_gate_', 'hold_', 'coupler_'))
        if name in bounds:
            lo, hi = bounds[name]
            value = {'type': 'integer' if name in ('drive_line', 'hold_enabled', 'idle_active', 'idle_tone_smooth', 'sizzle_smooth', 'hold_smooth', 'ecr_walsh', 'dd_pulses') else 'number', 'minimum': lo, 'maximum': hi}
        elif name == 'dd_sequence':
            value = {'type': 'string', 'enum': ['off', 'cpmg', 'xy4', 'xy8']}
        elif name == 'readout_weights':
            value = {'type': 'array', 'minItems': 1, 'maxItems': 256, 'items': {'type': 'array', 'minItems': 2, 'maxItems': 2, 'items': {'type': 'number', 'minimum': -100, 'maximum': 100}}}
        elif name in ('sizzle_network_amp', 'sizzle_network_phase', 'post_gate_network_phase'):
            lo, hi = (0, 2) if name == 'sizzle_network_amp' else (-20, 20)
            value = {'type': 'array', 'minItems': n, 'maxItems': n, 'items': {'type': 'number', 'minimum': lo, 'maximum': hi}}
        elif name in ('cr_cancel', 'cr_rotary'):
            value = complex_schema(2)
        elif name == 'source_mix':
            value = {'type': 'array', 'minItems': n, 'maxItems': n, 'items': {'type': 'array', 'minItems': 2, 'maxItems': 2, 'items': {'type': 'number', 'minimum': -2, 'maximum': 2}}}
        elif name == 'iq_means3':
            value = {'type': 'array', 'minItems': 3, 'maxItems': 3, 'items': complex_schema(2000)}
        else:
            limit = 20 if name in ('post_gate_phase', 'hold_frame') else 2
            value = {'type': 'array', 'minItems': 2, 'maxItems': 2, 'items': {'type': 'number', 'minimum': -limit, 'maximum': limit}}
        fields[name] = {'description': DESCRIPTIONS.get(name, 'Independent siZZle idle workpoint' if name.startswith('hold_') else 'Source mixing: input qubit to physical source complex weights [real,imag]'), 'value': value, 'index': {'type': 'array', 'minItems': 2, 'maxItems': 2, 'items': {'type': 'integer', 'minimum': 0, 'maximum': n - 1}} if pair else {'type': 'integer', 'minimum': 0, 'maximum': 0 if name == 'idle_active' else n - 1}}
    return {'fields': fields, 'max_updates_per_call': 64, 'pair_indices': [list(e) for edge in edges for e in (edge, edge[::-1])], 'constraints': ['All values must be finite. Updates in one call are atomic.', 'Pair fields require a directed physical edge. Status dictionary keys are strings; update indices are integer or [control,target].', 'Stored CR and siZZle duration >= 2*rise. ECR additionally requires total cr_duration >= 4*cr_rise.', 'Compiled CNOT additionally requires each spectator pi_duration <= cr_duration/2 for scheduled echo pulses.', 'Changing duration does not automatically rescale amplitude. Hardware laws remain fixed; flux_bias changes their commanded operating point.', 'DD uses finite pulses inside the requested idle window; CPMG count must be even. Readout weights cannot be all zero.']}

def complex_schema(bound):
    return {'type': 'object', 'required': ['real', 'imag'], 'additionalProperties': False, 'properties': {k: {'type': 'number', 'minimum': -bound, 'maximum': bound} for k in ('real', 'imag')}}
